mapper.select:
SELECT  FROM report_definition
WHERE workspace_id = #{workspaceId}
ORDER BY updated_at DESC, id DESC

mapper.update:
UPDATE report_definition
SET name = #{name}, description = #{description}, cadence = #{cadence},
    template_key = #{templateKey}, config_json = #{configJson}
WHERE workspace_id = #{workspaceId} AND id = #{id}

