mapper.select:
SELECT CONCAT(COALESCE(d.currency, ''), ':', ) AS group_key, CONCAT(COALESCE(d.currency, ''), ' · ', ) AS group_label, COALESCE(d.currency, '') AS unit, COALESCE(SUM(GREATEST(d.value, 0)), 0) AS best_value, COALESCE(SUM(GREATEST(d.value, 0) * ), 0) AS weighted_value, COALESCE(SUM( GREATEST(d.value, 0) * * ), 0) AS worst_value FROM deal d LEFT JOIN pipeline p ON p.id = d.pipeline_id AND p.workspace_id = #{query.workspaceId} LEFT JOIN stage s ON s.id = d.stage_id AND s.pipeline_id = d.pipeline_id AND s.workspace_id = #{query.workspaceId} LEFT JOIN company c ON c.id = d.company_id AND c.workspace_id = #{query.workspaceId} LEFT JOIN ( SELECT closed_stage_deal.pipeline_id, closed_stage_deal.stage_id, 1.0 * SUM(CASE WHEN closed_stage_deal.won = TRUE THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0) AS win_rate FROM deal closed_stage_deal WHERE closed_stage_deal.workspace_id = #{query.workspaceId} AND closed_stage_deal.won IS NOT NULL GROUP BY closed_stage_deal.pipeline_id, closed_stage_deal.stage_id ) legacy_stage_history ON legacy_stage_history.pipeline_id = d.pipeline_id AND legacy_stage_history.stage_id = d.stage_id LEFT JOIN ( SELECT stage_event.stage_id, COUNT(DISTINCT CASE WHEN reached_deal.won = TRUE THEN stage_event.deal_id END) AS won_count, COUNT(DISTINCT stage_event.deal_id) AS deal_count FROM deal_stage_history stage_event JOIN deal reached_deal ON reached_deal.id = stage_event.deal_id AND reached_deal.workspace_id = stage_event.workspace_id WHERE stage_event.workspace_id = #{query.workspaceId} AND stage_event.stage_id IS NOT NULL AND stage_event.conversion_eligible = TRUE AND reached_deal.workspace_id = #{query.workspaceId} AND reached_deal.won IS NOT NULL GROUP BY stage_event.stage_id ) reached_stage_history ON reached_stage_history.stage_id = d.stage_id CROSS JOIN ( SELECT 1.0 * SUM(CASE WHEN workspace_deal.won = TRUE THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0) AS win_rate FROM deal workspace_deal WHERE workspace_deal.workspace_id = #{query.workspaceId} AND workspace_deal.won IS NOT NULL ) workspace_history WHERE d.workspace_id = #{query.workspaceId} AND d.won IS NULL AND d.expected_close_date >= #{query.startDate} AND d.expected_close_date < #{query.endDateExclusive}
GROUP BY group_key, group_label, unit
ORDER BY MIN(d.pipeline_id), MIN(s.position), group_key ORDER BY group_key

SELECT AS group_key, AS group_label, 'count' AS unit, COUNT(*) AS value FROM activity a WHERE a.workspace_id = #{query.workspaceId} AND a.timestamp >= #{query.startUtc} AND a.timestamp < #{query.endUtc}
AND a.created_by_id IN #{id}
AND EXISTS (SELECT 1 FROM deal ad WHERE ad.workspace_id = #{query.workspaceId} AND ad.id = a.deal_id AND ad.pipeline_id IN #{id})
GROUP BY group_key, group_label ORDER BY group_key

SELECT  AS group_key,
        AS group_label,
       'count' AS unit,
       COUNT(*) AS value
FROM task t
WHERE t.workspace_id = #{query.workspaceId}
  AND t.updated_at >= #{query.startUtc} AND t.updated_at < #{query.endUtc}

  AND t.assigned_to_id IN
  #{id}


  AND t.status IN
  #{status}

GROUP BY group_key, group_label
ORDER BY group_key

SELECT network_company.id AS company_id,
       network_company.name AS company_name,
       network_deal.currency AS currency,
       COALESCE(SUM(GREATEST(network_deal.value, 0)), 0) AS account_value
FROM deal network_deal
JOIN company network_company ON network_company.id = network_deal.company_id
  AND (
    network_company.workspace_id = #{query.workspaceId}
    OR EXISTS (
      SELECT 1
      FROM company_share network_company_share
      JOIN workspace vws ON vws.id = network_company_share.workspace_id
        AND vws.id = #{query.workspaceId}
      JOIN workspace ows ON ows.id = network_company.workspace_id
        AND ows.org_id = vws.org_id
      WHERE network_company_share.company_id = network_company.id
        AND network_company_share.workspace_id = #{query.workspaceId}
    )
  )
WHERE network_deal.workspace_id = #{query.workspaceId}
  AND network_deal.won IS NULL

  AND network_deal.pipeline_id IN
  #{id}


  AND network_deal.owner_id IN
  #{id}


  AND 'open' IN
  #{status}


  AND EXISTS (
    SELECT 1
    FROM company_tag network_company_tag
    JOIN tag network_tag ON network_tag.id = network_company_tag.tag_id
      AND network_tag.workspace_id = #{query.workspaceId}
    WHERE network_company_tag.company_id = network_company.id
      AND network_company_tag.tag_id IN
      #{id}
  )

GROUP BY network_company.id, network_company.name, network_deal.currency
ORDER BY network_deal.currency, network_company.name, network_company.id
LIMIT #{limit}

SELECT p.id
FROM person p
WHERE p.created_at <= #{asOf}
  AND (
    p.workspace_id = #{workspaceId}
    OR EXISTS (
      SELECT 1
      FROM person_share ps
      JOIN workspace viewer_workspace ON viewer_workspace.id = ps.workspace_id
        AND viewer_workspace.id = #{workspaceId}
      JOIN workspace owner_workspace ON owner_workspace.id = p.workspace_id
        AND owner_workspace.org_id = viewer_workspace.org_id
      WHERE ps.person_id = p.id
        AND ps.workspace_id = #{workspaceId}
        AND ps.created_at <= #{asOf}
    )
  )
ORDER BY p.id

SELECT c.id
FROM company c
WHERE c.created_at <= #{asOf}
  AND (
    c.workspace_id = #{workspaceId}
    OR EXISTS (
      SELECT 1
      FROM company_share cs
      JOIN workspace viewer_workspace ON viewer_workspace.id = cs.workspace_id
        AND viewer_workspace.id = #{workspaceId}
      JOIN workspace owner_workspace ON owner_workspace.id = c.workspace_id
        AND owner_workspace.org_id = viewer_workspace.org_id
      WHERE cs.company_id = c.id
        AND cs.workspace_id = #{workspaceId}
        AND cs.created_at <= #{asOf}
    )
  )
ORDER BY c.id
